#define twoPi 6.28318530718
#define encodeScale .1

//https://www.desmos.com/calculator/u1seu4ah97
float angularEncode(vec2 p){
    float d = length(p);
    float theta = atan(p.y, p.x) + (twoPi * floor(d / (encodeScale * twoPi)));
    return theta;
}

vec2 angularDecode(float theta){
    float r = encodeScale * theta;
    return vec2(r * cos(theta), r * sin(theta));
}

float angularEncodev3(vec3 p){
    float a = angularEncode(p.xy);
    float b = angularEncode(vec2(p.z, 0.));
    return angularEncode(vec2(a,b));
}

vec3 angularDecodev3(float theta){
    vec2 ab = angularDecode(theta);
    vec3 xyz = vec3(angularDecode(ab.x), angularDecode(ab.y).x);
    return xyz;
}

float angularEncodev4(vec4 p){
    float a = angularEncode(p.xy);
    float b = angularEncode(p.zw);
    return angularEncode(vec2(a,b));
}

vec4 angularDecodev4(float theta){
    vec2 ab = angularDecode(theta);
    vec4 xyzw = vec4(angularDecode(ab.x), angularDecode(ab.y));
    return xyzw;
}
